// High School course unit (docs/design/COURSES.md, brought to docs/design/COURSE_QUALITY.md's bar on 10 Oct): AP Human Geography, Unit 2, Population and Migration (the course's
// public outline; our own wording and questions, nothing copied). Arithmetic density is people ÷ land area,
// physiological density is people ÷ arable land, and agricultural density is farmers ÷ arable land. The crude birth and
// death rates are births or deaths per 1,000 people a year; the rate of natural increase is (CBR - CDR) ÷ 10, as a
// percent; the rule of 70 puts doubling time at 70 ÷ the growth rate in percent. The dependency ratio is (people aged
// 0-14 + people 65 and over) ÷ people aged 15-64 × 100, and the sex ratio is males per 100 females. Replacement-level
// fertility is about 2.1 children per woman. The demographic transition model's stages: 1 high birth and death rates;
// 2 high births, falling deaths; 3 falling births, low deaths; 4 low births and deaths; 5 deaths above births. Migration
// is sorted by push (a reason to leave) or pull (a reason to come), internal or international, and forced or voluntary.
// Every country here is fictional and its numbers are chosen so each answer is a whole number or a terminating decimal;
// the sorted cases are the textbook definitions, read by hand. Also taught: where people live (about nine in ten north
// of the equator, clustered in East Asia, South Asia and Europe, in lowlands near water); carrying capacity; infant
// mortality (infant deaths per 1,000 live births) and life expectancy; the epidemiologic transition; Malthus (1798:
// population grows geometrically, food arithmetically; positive and preventive checks), Boserup and the Green
// Revolution, and neo-Malthusians; pro-natalist, anti-natalist and immigration policies; how women's education, paid work
// and family planning lower fertility; aging and the old-age dependency ratio (65+ ÷ 15-64 × 100); Ravenstein's laws
// (1880s) and intervening obstacles and opportunities; refugees (across a border), internally displaced people and
// asylum seekers; and remittances, brain drain, chain and step migration, guest workers, transhumance and
// counterurbanization.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Lesson figures use 640 × 280 screen positions, converted to the figure renderer's upward y axis.
   Labels stay inside the 44..596 × 56..248 drawing window; shapes reveal in order. */
const scene=(title,draw)=>{const pts={},polys=[],segs=[],circles=[],notes=[];let i=0;const point=(x,y)=>{const k='P'+i++;pts[k]=[x,280-y];return k;};
 const pen={box:(x,y,w,h,col=0)=>{const v=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>point(a,b)).join('');polys.push({v,col});},line:(x,y,u,v,col=0,arrows=0,dash=false,w=2)=>segs.push({v:point(x,y)+point(u,v),col,arrows,dash,w}),circle:(x,y,r,col=0)=>circles.push({c:point(x,y),r,col}),note:(x,y,text,col=0)=>notes.push({at:[x,280-y],text,col})};
 draw(pen);return {t:'figure',title,view:[44,596,32,224],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,circles,notes};};
const board=(title,lines)=>({t:'board',title,lines,box:true});
const art=(title,items)=>({t:'art',title,items:items.map(([src,x,label])=>({src:'hug/'+src+'.png',x,y:222,h:140,label}))});
/* Fictional age shares, youngest to oldest. Each sex sums to 50% of the total.
   Width = share × 3.6 pixels on BOTH sides of all three pyramids; equal-height age bands. */
const pyramids=()=>scene('Fictional age profiles (% of total)',d=>{const groups=[[12,10,8,7,5,4,3,1],[7,7,7,7,7,6,5,4],[4,5,6,7,8,8,7,5]],ages=['0–9','10–19','20–29','30–39','40–49','50–59','60–69','70+'];
 groups.forEach((values,k)=>{const cx=125+195*k;d.note(cx,72,['Expanding','Stable','Contracting'][k]);d.note(cx-26,91,'M',0);d.note(cx+26,91,'F',1);
 values.forEach((v,i)=>{const y=205-i*14,w=v*3.6;d.box(cx-w,y,w,11,0);d.box(cx,y,w,11,1);if(!k)d.note(50,y+5.5,ages[i],3);});
 d.line(cx-48,222,cx+48,222,3);for(const v of [-10,0,10]){d.line(cx+v*3.6,219,cx+v*3.6,225,3);d.note(cx+v*3.6,240,String(Math.abs(v)),3);}});});
/* Illustrative rates, not a country's observations. Stage numbers are schematic time positions.
   The shaded gap is births minus deaths. Stage 5 is an extension of the four-stage model. */
const births=[[1,42],[1.4,42],[2,41],[2.4,39],[3,29],[3.5,18],[4,12],[4.4,11],[5,7]],deaths=[[1,39],[1.4,40],[2,24],[2.4,14],[3,10],[3.5,9],[4,9],[4.4,10],[5,12]];
const transition={t:'plot',title:'DTM: fictional rates per 1,000',x:[1,5.5],y:[0,50],paths:[{pts:births},{pts:deaths}],areas:[{pts:[...births,...deaths.slice().reverse()],col:2}],points:[{x:1.4,y:42,label:'Births'},{x:2.4,y:14,label:'Deaths'}]};
const n=v=>v.toLocaleString('en-US');
const pct=v=>String(Math.round(v*1e6)/1e6);
const PUSH=[
 ['A civil war makes it dangerous to stay in a family\'s home country.','push'],
 ['Higher wages in a nearby city draw workers from the countryside.','pull'],
 ['A long drought ruins the farms in a region.','push'],
 ['A country offers religious freedom that a group does not have at home.','pull'],
 ['The only factory in a town closes and many people lose their jobs.','push'],
 ['A university with strong programs attracts students from abroad.','pull'],
 ['Rising sea levels keep flooding a coastal village.','push'],
 ['Relatives who already live in another country offer help settling in.','pull'],
 ['A government jails people for their political views.','push'],
 ['A region with a mild climate and many retirement communities attracts retirees.','pull'],
 ['An earthquake destroys most of the homes in a city.','push'],
 ['A booming tech industry in another country is hiring engineers.','pull'],
 ['Crime and violence make a neighbourhood unsafe.','push'],
 ['A country offers free health care and good schools.','pull']];
const PLACE=[
 ['A family moves from Ohio to Texas for a new job.','internal'],
 ['A nurse moves from the Philippines to Canada.','international'],
 ['A student moves from a village to the capital of the same country.','internal'],
 ['A worker moves from Mexico to the United States.','international'],
 ['A retired couple moves from New York to Florida.','internal'],
 ['A refugee family crosses the border from Syria into Turkey.','international']];
const FORCE=[
 ['People flee their homes as a war reaches their town.','forced'],
 ['A software developer accepts a better-paid job in another country.','voluntary'],
 ['A government moves a whole village to make way for a dam, and the people cannot refuse.','forced'],
 ['A young couple moves to a city they like for its music scene.','voluntary'],
 ['People are taken from their homeland and enslaved.','forced'],
 ['A family moves to be closer to their grandchildren.','voluntary']];
const SHAPE=[
 ['Its population pyramid has a very wide base that narrows quickly toward the top.','expanding'],
 ['Its population pyramid has bars of about the same width from the bottom up to old age.','stable'],
 ['Its population pyramid is narrower at the base than in the middle.','contracting'],
 ['It has many more children than young adults, and few old people.','expanding'],
 ['Each younger age group is smaller than the one just above it.','contracting'],
 ['Births have stayed low and steady for decades, so each age group is about the same size until old age.','stable']];
/* The four Try-it questions in pool form; the generator skips them. */
const TRY=['A fictional country has 40 million people and 200,000 square kilometers of land. What is its arithmetic density, in people per square kilometer?',
 'A fictional country has a crude birth rate of 30 and a crude death rate of 10. What is its rate of natural increase, as a percent?',
 'A fictional country\'s population is growing by 2% a year. By the rule of 70, about how many years will it take to double?',
 'A fictional country has 14 million people aged 65 and over and 40 million aged 15-64. What is its old-age dependency ratio?'];
/* lettered choices, the right one moved to position k */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
export default {
id:'geography-h-ap-hug-population-and-migration',subject:'geography',level:5,grade:9,standard:'AP Human Geography, Unit 2',
title:'Population and migration',
goal:'Explain where people live and what crowding does, compare densities, work out birth, death, infant mortality and growth rates, read population structure and aging, use the demographic and epidemiologic transitions, weigh Malthus and his critics, sort population policies, link women\'s lives to fertility, and explain the causes, kinds and effects of migration.',
points:20,
skills:{density:'Population distribution',capacity:'Consequences of distribution',structure:'Population composition',rates:'Population dynamics',dtm:'The demographic transition',malthus:'Malthus and his critics',policy:'Population policies',women:'Women and demographic change',aging:'Aging populations',migration:'Causes of migration',kinds:'Forced and voluntary migration',effects:'Effects of migration'},
outline:[['2.1','Population distribution',['density']],['2.2','Consequences of population distribution',['capacity']],['2.3','Population composition',['structure']],['2.4','Population dynamics',['rates']],['2.5','The demographic transition model',['dtm']],['2.6','Malthusian theory',['malthus']],['2.7','Population policies',['policy']],['2.8','Women and demographic change',['women']],['2.9','Aging populations',['aging']],['2.10','Causes of migration',['migration']],['2.11','Forced and voluntary migration',['kinds']],['2.12','Effects of migration',['effects']]],
steps:[
 {skill:"density",say:"Always choose the right denominator. Arithmetic density uses all land; physiological density uses only arable land. Agricultural density also uses arable land but counts farmers instead of everyone. This fictional district has 7,200 residents, 480 farmers, 90 square kilometers of land and 24 that can be farmed.",eq:"density = the relevant population ÷ the relevant land area",pic:board('Fictional district: densities',['Arithmetic: 7,200 ÷ 90 = 80 people/km²','Physiological: 7,200 ÷ 24 = 300 people/km²','Agricultural: 480 ÷ 24 = 20 farmers/km²']),
  check:{prompt:tryIt(TRY[0]),answer:200,options:[200,5,2000],hint:'Divide 40,000,000 people by 200,000 square kilometers.',pic:tab('A fictional country',[['people','40,000,000'],['land','200,000 km²']])}},
 {skill:"density",say:"People are distributed unevenly. East Asia, South Asia and Europe contain major population concentrations. Water, fertile land and accessible lowlands support settlement, while jobs and transport attract people to cities. A farming village and a crowded street make these physical and human influences easier to picture.",pic:art('Where people settle',[['farming-village',180,'Water + farmland'],['crowded-street',460,'Jobs + transport']])},
 {skill:"capacity",say:"Carrying capacity depends on resources, consumption, technology and trade, so density alone cannot tell us whether a place can support its people. Food imports can supplement local farms. Dense settlement can help transit and services reach many people, while also putting pressure on housing and water supplies.",pic:scene('What supports a city’s population?',d=>{d.box(70,90,135,40,2);d.note(137,110,'Local farms');d.box(70,180,135,40,1);d.note(137,200,'Food imports');d.box(340,124,184,62,0);d.note(432,146,'City');d.note(432,166,'People + services');d.line(214,112,330,145,2,1);d.line(214,198,330,166,1,1);d.note(320,240,'Supply must meet needs without depleting resources');})},
 {skill:"structure",say:"Read a population pyramid from the youngest group at the bottom to the oldest at the top. Each side shows one sex on the same percentage scale. A broad base suggests expansion; straighter sides suggest stability; a narrow base suggests contraction. These are clues, not forecasts: migration and future births also matter. Sex ratio is males per 100 females.",pic:pyramids()},
 {skill:"rates",say:"Birth and death rates count annual events per 1,000 residents. In this fictional country, 34 births minus 9 deaths leaves 25 additional people per 1,000, or 2.5 percent natural increase. Migration is excluded. The gap between the bars, rather than the birth rate alone, explains natural growth.",eq:"RNI (%) = (CBR - CDR) ÷ 10",pic:{t:'chart',kind:'bars',title:'Fictional rates per 1,000 per year',bars:[{label:'Birth rate (CBR)',value:34},{label:'Death rate (CDR)',value:9}]},
  check:{prompt:tryIt(TRY[1]),answer:2,options:[2,20,3],hint:'Subtract the death rate from the birth rate, then divide by 10.',pic:tab('Rates per 1,000',[['CBR','30'],['CDR','10']])}},
 {skill:"rates",say:"Now use the growth rate to estimate doubling time. If our fictional country keeps growing at 2.5 percent a year, with no net migration, the rule of 70 gives about 28 years. Enter 2.5, not 0.025, because this shortcut uses a percentage. It assumes sustained positive growth; zero or negative growth has no doubling time.",eq:"doubling time ≈ 70 ÷ annual growth rate in percent",pic:board('Fictional doubling time',['RNI = (34 - 9) ÷ 10 = 2.5%','No net migration: growth is 2.5% yearly','Doubling time ≈ 70 ÷ growth percent','70 ÷ 2.5 = about 28 years']),
  check:{prompt:tryIt(TRY[2]),answer:35,options:[35,140,70],hint:'Divide 70 by 2.',pic:tab('Growth',[['rate','2% a year']])}},
 {skill:"rates",say:"Health indicators use different denominators. Infant mortality counts deaths before age one per 1,000 live births, not per 1,000 residents. In this fictional case, 84 such deaths among 12,000 live births gives 7. Life expectancy uses current death rates; total fertility rate estimates lifetime births per woman at current age-specific fertility rates.",pic:board('Fictional infant mortality',['IMR = infant deaths ÷ live births × 1,000','IMR = 84 ÷ 12,000 × 1,000','IMR = 7 per 1,000 births'])},
 {skill:"dtm",say:"Trace births and deaths through the demographic transition: x marks stages and y counts annual events per 1,000 people. Stage 1 has high rates; in stage 2 deaths fall first and the gap widens. Births fall in stage 3; both rates are low in stage 4. The stage 5 extension shows births below deaths. The shaded gap means natural change, not migration. These fictional curves show a model, not a fixed timetable for every country.",pic:transition},
 {skill:"dtm",say:"The epidemiologic transition focuses on causes of death. As nutrition, clean water and medical care improve, infectious diseases and famine become less dominant. Chronic diseases account for more deaths as people live longer. This is a broad pattern, not a guarantee: infections can persist or return, including through new pathogens or drug resistance.",pic:scene('Changing causes of death',d=>{for(const [x,col,a,b] of [[65,0,'Infections','+ famine'],[257,1,'Prevention','+ treatment'],[449,2,'More chronic','disease']]){d.box(x,117,126,66,col);d.note(x+63,140,a,col);d.note(x+63,161,b,col);}d.line(197,150,249,150,0,1);d.line(389,150,441,150,1,1);d.note(320,80,'Earlier → later in the model');d.note(320,228,'Infectious diseases can persist or return');})},
 {skill:"malthus",say:"Malthus argued in 1798 that unchecked population could grow geometrically while food grew arithmetically. His positive checks, such as famine, raise deaths; preventive checks lower births. Boserup emphasized innovation under population pressure, and rising crop yields challenged a fixed food-growth path. Neo-Malthusians still emphasize environmental limits.",pic:scene('Malthus and Boserup',d=>{d.box(70,123,140,50,0);d.note(140,143,'Population');d.note(140,162,'pressure');d.line(221,143,335,108,1,1);d.line(221,157,335,198,2,1);d.box(345,80,220,54,1);d.note(455,99,'Malthus: food limits');d.note(455,120,'Checks restrain growth');d.box(345,175,220,54,2);d.note(455,195,'Boserup: innovation');d.note(455,216,'Food output can rise');})},
 {skill:"policy",say:"Population policies target different parts of population change. Pro-natalist policies encourage births; anti-natalist policies aim to reduce births. Immigration policies regulate entry. The arrows show policy aims, not guaranteed results: personal choices, access to services and wider economic conditions affect how people respond.",pic:scene('Population policy aims',d=>{for(const [y,left,right,col] of [[98,'Pro-natalist','More births',0],[156,'Anti-natalist','Fewer births',1],[214,'Immigration policy','Entry rules',2]]){d.box(75,y-18,185,36,col);d.note(167,y,left,col);d.line(270,y,365,y,col,1);d.box(377,y-18,185,36,col);d.note(469,y,right,col);}})},
 {skill:"women",say:"Education, paid work and access to family planning can expand women’s choices about when and whether to have children. These changes often accompany lower fertility in stage 3, rather than determining every person’s family size. Replacement fertility is about 2.1 children per woman where mortality is low; age structure and migration also influence future population size.",pic:art('Education expands choices',[['woman-studying',320,'Schooling, work and control over family size']])},
 {skill:"aging",say:"Low fertility and longer lives can increase the older share of a population. The old-age dependency ratio compares ages 65 and over with ages 15–64; the total ratio also includes ages 0–14. These age groups are a planning convention, not a claim that every adult works. A higher ratio can increase demand for pensions and care.",eq:"old-age dependency = ages 65+ ÷ ages 15–64 × 100",pic:board('Fictional dependency ratios',['Millions: young 6; older 8; working 32','Old-age ratio = 8 ÷ 32 × 100 = 25','25 older people per 100 working-age people','Total ratio = (6 + 8) ÷ 32 × 100 = 43.75','Total includes young + older']),
  check:{prompt:tryIt(TRY[3]),answer:35,options:[35,54,26],hint:'Divide the people 65 and over by the people 15-64, then multiply by 100.',pic:tab('In millions',[['ages 65+','14'],['ages 15-64','40']])}},
 {skill:"migration",say:"Migration reflects push factors at the origin and pull factors at the destination. Ravenstein observed that many moves are short, work often matters, and flows have counterflows. A route can change along the way: a job in an intermediate town is an intervening opportunity, while a closed route is an obstacle. These are tendencies, not rules for every migrant.",pic:scene('Fictional migration route',d=>{for(const [x,label] of [[110,'Origin'],[305,'Town'],[530,'City']]){d.circle(x,145,15,0);d.note(x,105,label);}d.line(130,145,282,145,0,1);d.line(326,145,508,145,0,1,true);d.line(281,188,130,188,1,1);d.line(424,121,424,170,3,0,false,5);d.note(110,70,'Push: lost work');d.note(530,70,'Pull: jobs');d.note(305,217,'Opportunity: a job here');d.note(437,185,'Obstacle');d.note(196,239,'Counterflow');})},
 {skill:"kinds",say:"Classify a move by both the border and the degree of choice. Internal migration stays within a country; international migration crosses a border. A person forced from home who stays inside is internally displaced. Refugees flee persecution, war or violence across a border. An asylum seeker awaits a protection decision. Voluntary moves involve choice, though severe pressures can narrow it.",pic:scene('Forced displacement (schematic)',d=>{d.box(70,90,270,124,0);d.box(365,90,205,124,1);d.note(203,71,'Country A');d.note(467,71,'Country B');d.circle(107,150,7,3);d.line(120,144,281,119,0,1);d.note(237,104,'IDP: stays inside');d.line(120,166,477,185,1,1);d.note(473,157,'Refugee');d.note(473,199,'Crosses border');d.note(320,240,'Asylum seeker: protection claim awaiting decision');})},
 {skill:"effects",say:"Migration links origins and destinations. Remittances are money sent home; losing skilled workers can create brain drain, while destinations gain workers and cultural influences. Family networks can encourage chain migration. Step migration means moving through successive places. Guest workers move for limited work periods; transhumance follows seasonal pastures. Counterurbanization moves people from cities to smaller settlements.",pic:art('One move changes two communities',[['farming-village',180,'Origin: remittances; skills may leave'],['moving-family',460,'Destination: people, work, culture']])},
 {skill:"effects",summary:true,say:"Connect the unit by explaining population change in a place: births add people, deaths subtract people, and migration can do either. Density and age structure help explain the resulting needs. Use transition models, policy, women’s choices and resource limits as context. Check denominators and remember that natural increase excludes migration.",pic:scene('Unit 2: population change',d=>{d.box(246,123,148,50,0);d.note(320,148,'Population');d.note(116,99,'Births add');d.line(116,119,236,140,2,1);d.note(514,99,'Deaths subtract');d.line(402,140,514,119,1,1);d.note(126,213,'Immigration adds');d.line(134,192,236,160,2,1);d.note(511,213,'Emigration subtracts');d.line(402,160,505,192,1,1);d.note(320,242,'Age structure + density → changing needs');})}],
progression:{requires:['geography-e-population-density','geography-m-population-pyramids','geography-m-migration'],operations:2,demand:'Divide populations by the right land area or age group, turn per-1,000 rates into percents and doubling times, follow Malthus\'s two sequences, and sort countries, policies and migrants by the definitions behind each model.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 /* density: [people, land km², arable km², farmers] */
 for(const [p,l,a,f] of [[30e6,150000,20000,4e6],[12e6,60000,8000,1.6e6],[90e6,300000,45000,9e6],[5e6,250000,10000,1.5e6],[64e6,160000,32000,3.2e6],[18e6,450000,6000,2.4e6],[8e6,40000,16000,0.8e6],[150e6,600000,100000,30e6]]){
  const lead=`A fictional country has ${n(p)} people and ${n(l)} square kilometers of land, ${n(a)} of them arable`,pic=tab('A fictional country',[['people',n(p)],['land',`${n(l)} km²`],['arable land',`${n(a)} km²`],['farmers',n(f)]]);
  put('density',`${lead}. What is its arithmetic density, in people per square kilometer?`,p/l,pic,`Arithmetic density = people ÷ all land = ${n(p)} ÷ ${n(l)} = ${pct(p/l)} people per km².`);
  put('density',`${lead}. What is its physiological density, in people per square kilometer of arable land?`,p/a,pic,`Physiological density = people ÷ arable land = ${n(p)} ÷ ${n(a)} = ${pct(p/a)} people per km².`);
  put('density',`${lead}, and ${n(f)} of its people are farmers. What is its agricultural density, in farmers per square kilometer of arable land?`,f/a,pic,`Agricultural density = farmers ÷ arable land = ${n(f)} ÷ ${n(a)} = ${pct(f/a)} farmers per km².`);}
 /* rates: CBR and CDR from counts, RNI, doubling time */
 for(const [b,p] of [[24000,1200000],[90000,3000000],[13500,1500000],[42000,1000000],[8800,800000],[175000,5000000]]){const r=b/p*1000;
  put('rates',`A fictional country of ${n(p)} people had ${n(b)} births last year. What is its crude birth rate, in births per 1,000 people?`,r,tab('Last year',[['people',n(p)],['births',n(b)]]),`CBR = ${n(b)} ÷ ${n(p)} × 1,000 = ${pct(r)}.`);}
 for(const [d,p] of [[12000,1500000],[36000,4000000],[7000,700000],[54000,6000000]]){const r=d/p*1000;
  put('rates',`A fictional country of ${n(p)} people had ${n(d)} deaths last year. What is its crude death rate, in deaths per 1,000 people?`,r,tab('Last year',[['people',n(p)],['deaths',n(d)]]),`CDR = ${n(d)} ÷ ${n(p)} × 1,000 = ${pct(r)}.`);}
 for(const [b,d] of [[40,12],[25,10],[18,8],[35,7],[12,10],[9,11],[44,16],[22,7]]){const r=(b-d)/10;
  put('rates',`A fictional country has a crude birth rate of ${b} and a crude death rate of ${d}. What is its rate of natural increase, as a percent?`,r,tab('Rates per 1,000',[['CBR',`${b}`],['CDR',`${d}`]]),`RNI = (${b} - ${d}) ÷ 10 = ${pct(r)}%${r<0?', so the population is shrinking naturally':''}.`);}
 for(const g of [1,3.5,1.4,0.7,2.8,5,0.5,1.75]){const t=70/g;
  put('rates',`A fictional country's population is growing by ${g}% a year. By the rule of 70, about how many years will it take to double?`,t,tab('Growth',[['rate',`${g}% a year`]]),`70 ÷ ${g} = ${pct(t)} years.`);}
 /* structure: dependency ratio, sex ratio, pyramid shapes, replacement level */
 for(const [y,o,w] of [[12,4,20],[30,6,48],[9,6,30],[45,15,40],[14,10,48],[16,4,80],[27,3,40],[8,12,50]]){const r=(y+o)/w*100;
  put('structure',`A fictional country has ${y} million people aged 0-14, ${o} million aged 65 and over, and ${w} million aged 15-64. What is its dependency ratio?`,r,tab('In millions',[['ages 0-14',`${y}`],['ages 65+',`${o}`],['ages 15-64',`${w}`]]),`(${y} + ${o}) ÷ ${w} × 100 = ${pct(r)} dependents for every 100 people of working age.`);}
 for(const [m,f] of [[51000,50000],[48000,50000],[105000,100000],[93000,100000],[6300,6000],[4900,5000]]){const r=m/f*100;
  put('structure',`A fictional town has ${n(m)} males and ${n(f)} females. What is its sex ratio, in males per 100 females?`,r,tab('A fictional town',[['males',n(m)],['females',n(f)]]),`${n(m)} ÷ ${n(f)} × 100 = ${pct(r)} males per 100 females.`);}
 for(const [d,s] of SHAPE)put('structure',`${d} Is the population expanding, stable, or contracting?`,s,tab('Population structure',[['clue',d]],['']),s==='expanding'?'Many young people and few old people mean the population is growing: expanding.':s==='stable'?'Age groups of similar size mean little growth: stable.':'Fewer young people than older ones mean births have fallen, and the population is usually shrinking or soon will: contracting.');
 for(const t of [1.6,3.4,1.2,2.8,1.9,4.5]){const ab=t>2.1?'above':'below';
  put('structure',`A fictional country has a total fertility rate of ${t} children per woman. Is that above or below replacement level, which is about 2.1?`,ab,tab('Fertility',[['TFR',`${t}`],['replacement','about 2.1']]),`${t} is ${ab} 2.1. Where death rates are low, and without migration, that means the population will in the long run ${ab==='above'?'keep growing':'shrink'}.`);}
 /* dtm: from rates, and from descriptions */
 const STAGE=(b,d)=>b<d?5:b>=35&&d>=30?1:b>=30&&d<30?2:b>=17&&d<15?3:4;
 for(const [b,d] of [[45,40],[42,38],[48,35],[42,15],[38,20],[40,12],[28,8],[24,9],[20,8],[32,18],[11,9],[12,10],[13,8],[8,11],[9,12],[7,10]]){const st=STAGE(b,d);
  put('dtm',`A fictional country has a crude birth rate of ${b} and a crude death rate of ${d} per 1,000. Which stage of the demographic transition model (1 to 5) fits it best?`,st,tab('Rates per 1,000',[['CBR',`${b}`],['CDR',`${d}`]]),['','Both rates are high, so it is stage 1.','Births are high but deaths have fallen, so it is stage 2.','Deaths are low and births are falling, so it is stage 3.','Both rates are low, so it is stage 4.','Deaths are higher than births, so it is stage 5.'][st]);}
 for(const [d,st] of [['Most people farm, many children die in infancy, and the population barely grows.',1],['Clean water and vaccines have just arrived, so the death rate is dropping fast while families stay large.',2],['Women are staying in school longer and families are getting smaller, while the death rate is already low.',3],['Both birth and death rates are low and the population is almost steady.',4],['The population is getting older and smaller, with more funerals than births each year.',5],['Growth is at its fastest, because births are still high while deaths have fallen.',2],['Famine and disease keep the death rate as high as the birth rate.',1],['The birth rate has dropped to about the death rate after years of decline.',4],['Cities are growing and the birth rate has started to come down from its peak.',3]])
  put('dtm',`${d} Which stage of the demographic transition model (1 to 5) is this?`,st,tab('The clue',[['clue',d]],['']),['','Stage 1: high birth and death rates.','Stage 2: deaths falling, births still high.','Stage 3: births falling, deaths low.','Stage 4: low births and deaths.','Stage 5: deaths above births.'][st]);
 /* migration: push or pull, internal or international, forced or voluntary */
 for(const [s,k] of PUSH)put('migration',`${s} Is this a push factor or a pull factor?`,k,tab('Migration',[['case',s]],['']),k==='push'?'It is a reason to leave a place, so it is a push factor.':'It is a reason to move to a place, so it is a pull factor.');
 for(const [s,k] of PLACE)put('kinds',`${s} Is this internal or international migration?`,k,tab('Migration',[['case',s]],['']),k==='internal'?'The move stays inside one country, so it is internal migration.':'The move crosses a border between countries, so it is international migration.');
 for(const [s,k] of FORCE)put('kinds',`${s} Is this forced or voluntary migration?`,k,tab('Migration',[['case',s]],['']),k==='forced'?'The people have no real choice, so it is forced migration.':'The people choose to move, so it is voluntary migration.');
 const ask=(skill,rows,pic,k0=0)=>rows.forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k+k0);put(skill,`${q} ${c.text}. Answer A, B or C.`,c.letter,pic,why||`The answer is ${right}.`,[right]);});
 /* density: where people live and why */
 ask('density',[['About what share of the world\'s people live north of the equator?','about nine in ten',['about half','about one in ten'],'Most of Earth\'s land, and most people, lie in the Northern Hemisphere. Estimates put the share north of the equator at about 87 to 90 percent, close to nine in ten.'],
  ['Which kinds of places hold the most people?','lowlands near coasts and rivers, with fertile soil and a mild climate',['high mountains and deserts','the polar regions'],'People cluster in lowlands near coasts and rivers, where there is water, fertile soil, a mild climate and easy transport. Mountains, deserts and poles are sparse.'],
  ['Which three areas hold the largest clusters of people?','East Asia, South Asia and Europe',['Siberia, the Sahara and Antarctica','the Amazon, Greenland and Central Australia'],'East Asia, South Asia and Europe hold the largest clusters of people. Siberia, the Sahara and Antarctica are among the emptiest places.'],
  ['Why do few people live in the Sahara?','it is very dry, so water and farming are scarce',['it is too close to the equator to farm anything','laws forbid people from living there'],'The Sahara gets very little rain, so water is scarce and farming is hard. That keeps the population low, mostly near oases and the Nile.'],
  ['Which of these is a human (not physical) factor that draws people to a place?','jobs in a growing city',['a mild climate','fertile river soil'],'Jobs are a human factor, created by people. Climate and soil are physical factors of the environment.']],tab('Where people live',[['many people','coasts, rivers, lowlands, mild climates'],['few people','deserts, high mountains, polar regions']],['']));
 /* capacity: carrying capacity and the effects of density */
 for(const [cap,pop] of [[50000,62000],[80000,60000],[1200000,1500000],[400000,400000]]){const pic=tab('A fictional island',[['carrying capacity',n(cap)],['population',n(pop)]]);
  put('capacity',`A fictional island can support ${n(cap)} people without running down its resources, and ${n(pop)} people live there. What percent of its carrying capacity is its population?`,Math.round(pop/cap*100*1e6)/1e6,pic,`${n(pop)} ÷ ${n(cap)} × 100 = ${pct(pop/cap*100)}%${pop>cap?': more people than the land can support for long':pop<cap?': below its carrying capacity':': right at its carrying capacity'}.`);}
 ask('capacity',[['What is carrying capacity?','the largest population an area can support without running down its resources',['the number of people who live in an area today','the total land area of a country'],'Carrying capacity is the largest population an area can support without using up or damaging its resources. It is not today\'s population.'],
  ['When is a place overpopulated?','when its people outrun what its resources can support',['whenever its density is above 100 people per square kilometer','when it has more children than old people'],'Overpopulation means more people than resources can support. It is not set by density: a crowded rich city may not be overpopulated.'],
  ['Why can two places with the same land support different numbers of people?','technology and trade change how much food and income the land provides',['carrying capacity depends only on area','people in one place need no food'],'Technology, like irrigation and fertilizer, and trade, like importing food, change how many people the same land can support.'],
  ['Which density best shows the pressure of people on farmland?','physiological density',['arithmetic density','the sex ratio'],'Physiological density is people per unit of arable land, so it shows the pressure of people on farmland. Arithmetic density uses total land.'],
  ['Which is a common problem in very crowded cities?','housing, water and transport are strained',['there are too few customers for shops','services cost more per person to provide'],'Very crowded cities can strain housing, water and transport as many people compete for them. Higher costs per person are a problem of sparse areas.'],
  ['Which is an advantage of high population density?','services like hospitals and transit can reach many people at once',['every family gets more land','there is less traffic'],'With many people close together, one hospital or transit line can serve many people at once, so services cost less per person.'],
  ['A country imports most of its food. What does this mean for its carrying capacity?','trade lets it support more people than its own farms could feed',['it has no carrying capacity','imports lower its population'],'By importing food, a country can support more people than its own farms could feed. Trade raises its effective carrying capacity.']],tab('Carrying capacity',[['under capacity','resources to spare'],['over capacity','resources run down']],['Means']));
 /* rates: infant mortality and life expectancy */
 for(const [d,b] of [[450,30000],[1200,40000],[90,18000],[2400,60000],[56,16000]]){const r=d/b*1000;
  put('rates',`In a fictional country, ${n(d)} babies died before their first birthday out of ${n(b)} live births last year. What is its infant mortality rate, per 1,000 live births?`,Math.round(r*1e6)/1e6,tab('Last year',[['live births',n(b)],['infant deaths',n(d)]]),`IMR = ${n(d)} ÷ ${n(b)} × 1,000 = ${pct(r)}.`);}
 ask('rates',[['What does the infant mortality rate measure?','deaths of babies under one year old per 1,000 live births',['all deaths per 1,000 people','births per 1,000 women'],'The infant mortality rate counts deaths of babies under age one per 1,000 live births. All deaths per 1,000 people is the crude death rate.'],
  ['What is life expectancy?','the average number of years a newborn can expect to live at current death rates',['the age of the oldest person in a country','the average age of everyone alive today'],'Life expectancy is how long a newborn can expect to live on average if today\'s death rates stay the same. It is not the oldest person\'s age.'],
  ['Why is the infant mortality rate often used as a sign of a country\'s development?','babies\' survival depends on clean water, nutrition and health care',['it counts only rich families','it measures how many babies are born'],'Babies survive when families have clean water, good nutrition and health care, so infant mortality is a good sign of development.'],
  ['What is the total fertility rate?','the average number of children a woman has in her lifetime',['births per 1,000 people a year','the number of women in a country'],'The total fertility rate is the average number of children a woman would have in her lifetime at current rates. Births per 1,000 is the crude birth rate.']],tab('Rates',[['IMR','infant deaths per 1,000 births'],['life expectancy','years a newborn can expect'],['TFR','children per woman']],['Means']));
 /* dtm: the epidemiologic transition */
 ask('dtm',[['What does the epidemiologic transition describe?','how the main causes of death change as a country develops',['how birth rates change','how people move between countries'],'The epidemiologic transition describes how the main causes of death shift as a country develops, from infections to chronic diseases.'],
  ['In the first stage of the epidemiologic transition, what kills most people?','infectious diseases, famine and poor sanitation',['heart disease and cancer in old age','car accidents'],'In the first stage, infectious diseases, famine and poor sanitation kill many people, often young. Heart disease in old age comes later.'],
  ['In the later stages of the epidemiologic transition, what causes most deaths?','chronic diseases such as heart disease and cancer, mostly in old age',['plague and famine','infections among infants'],'In later stages, more people live to old age, so chronic diseases like heart disease and cancer cause most deaths.'],
  ['What helps pandemics recede and death rates fall in the middle stages?','vaccines, medicine and clean water',['higher birth rates','moving to farms'],'Vaccines, medicine, clean water and sanitation cut deaths from infections, so pandemics recede and death rates fall.'],
  ['Some geographers add a stage in which infectious diseases return. What could cause that?','drug-resistant germs or new viruses spreading',['every person living past 100','an end to all travel'],'Some geographers add a stage when infections return, through drug-resistant germs or new viruses spreading quickly with travel.']],tab('Epidemiologic transition',[['early','infections, famine'],['middle','pandemics recede'],['late','heart disease, cancer']],['Main killers']),1);
 /* malthus: Malthus, his checks and his critics */
 for(const [yrs,what] of [[100,'people'],[100,'food'],[75,'gap'],[50,'gap']]){const steps=yrs/25,pop=2**steps,food=1+steps;
  put('malthus',`In Malthus's model, a population of 1 million doubles every 25 years, while the food supply starts at enough for 1 million and grows by enough for 1 million more every 25 years. After ${yrs} years, ${what==='people'?'how many million people are there':what==='food'?'enough food for how many million people is there':'how many million more people are there than the food can feed'}?`,what==='people'?pop:what==='food'?food:pop-food,tab('Malthus\'s model',[['people','1, 2, 4, 8, 16 million'],['food for','1, 2, 3, 4, 5 million']]),`After ${steps} doublings the population is ${pop} million; food grows by 1 a step, to ${food} million.${what==='gap'?` The gap is ${pop} - ${food} = ${pop-food} million.`:''}`);}
 ask('malthus',[['What did Thomas Malthus argue in 1798?','population grows faster than the food supply, so it is held back by famine, disease or war',['food always grows faster than population','population can never grow'],'Malthus argued in 1798 that population tends to grow faster than food, so it is held back by famine, disease and war.'],
  ['In Malthus\'s view, how do population and food grow?','population geometrically (1, 2, 4, 8) and food arithmetically (1, 2, 3, 4)',['both geometrically','food geometrically and population arithmetically'],'Malthus said population grows geometrically (1, 2, 4, 8) while food grows only arithmetically (1, 2, 3, 4), so population outruns food.'],
  ['Malthus called famine, disease and war "positive checks". What do they do?','raise the death rate',['lower the birth rate','raise food output'],'Positive checks, such as famine, disease and war, limit population by raising the death rate.'],
  ['Malthus\'s "preventive checks", such as marrying later, do what?','lower the birth rate',['raise the death rate','raise food output'],'Preventive checks, such as marrying later or having fewer children, limit population by lowering the birth rate.'],
  ['How did Esther Boserup answer Malthus?','population pressure pushes farmers to find ways to grow more food',['famine is the only way to limit population','farming cannot be improved'],'Boserup argued that population pressure pushes farmers to farm more intensively and invent new methods, so food output rises.'],
  ['Why do critics say Malthus was wrong about food?','new technology, such as the Green Revolution, raised food output faster than he expected',['the world\'s population has shrunk since 1798','people stopped eating grain'],'Critics note that technology, such as the Green Revolution\'s seeds, fertilizer and irrigation, raised food output faster than Malthus expected.'],
  ['What do neo-Malthusians argue today?','resources and the environment may still limit population growth',['population cannot affect the environment','food will never be a problem again'],'Neo-Malthusians argue that resources and the environment, such as water, soil and climate, may still limit population growth.']],tab('Malthus and his critics',[['Malthus','population outruns food'],['Boserup','pressure drives new farming methods'],['neo-Malthusians','resources still set limits']],['Argued']),2);
 /* policy: anti-natalist, pro-natalist and immigration policies */
 ask('policy',[['A government pays families a bonus for each new baby. What kind of policy is this?','pro-natalist',['anti-natalist','an immigration policy'],'Paying families for each new baby encourages people to have more children. That is a pro-natalist policy.'],
  ['China\'s former one-child policy is an example of what kind of policy?','anti-natalist',['pro-natalist','an immigration policy'],'China\'s one-child policy, from 1980 until it was replaced in 2016, tried to limit births. That makes it an anti-natalist policy.'],
  ['A government gives free family planning services to lower the birth rate. What kind of policy is this?','anti-natalist',['pro-natalist','an immigration policy'],'Free family planning helps people have fewer children, lowering the birth rate. That is an anti-natalist policy.'],
  ['A country with very low fertility offers long paid parental leave and cheap childcare. What is the aim?','to encourage people to have more children',['to lower the birth rate','to stop immigration'],'Paid parental leave and cheap childcare make raising children easier, aiming to raise a very low birth rate.'],
  ['A country admits immigrants using a points system that rewards skills and education. What kind of policy is this?','an immigration policy',['a pro-natalist policy','an anti-natalist policy'],'A points system decides which immigrants may enter, so it is an immigration policy. It does not aim to change birth rates.'],
  ['Why might a country with an aging population adopt pro-natalist policies?','to raise births and grow the future workforce',['to make its population older','to lower its birth rate'],'An aging country with few births faces a shrinking workforce. Pro-natalist policies try to raise births to grow future workers.'],
  ['Why might a fast-growing, poor country adopt anti-natalist policies?','to slow growth so schools, jobs and food can keep up',['to make its population grow faster','to attract immigrants'],'If a population grows faster than schools, jobs and food can keep up, slowing growth gives services time to catch up.'],
  ['A country sets a limit on how many people may immigrate each year. What is this limit called?','a quota',['a remittance','a refugee'],'A quota is a limit on how many people may immigrate each year. Remittances are money sent home, and refugees are people fleeing danger.'],
  ['What is a pro-natalist policy?','a policy that encourages people to have more children',['a policy that encourages people to have fewer children','a policy about who may immigrate'],'A pro-natalist policy encourages people to have more children, often with payments, tax breaks or paid leave.'],
  ['What is an anti-natalist policy?','a policy that encourages people to have fewer children',['a policy that encourages people to have more children','a policy about who may emigrate'],'An anti-natalist policy encourages people to have fewer children, through family planning or limits on births.']],tab('Population policies',[['pro-natalist','raise births'],['anti-natalist','lower births'],['immigration','decide who moves in']],['Aim']));
 /* women: education, work and fertility */
 ask('women',[['As more girls finish school, what usually happens to a country\'s total fertility rate?','it falls',['it rises','it stays the same'],'As more girls finish school, they tend to marry later and have fewer children, so the total fertility rate usually falls.'],
  ['Why do women with more education tend to have fewer children?','they often marry later, work for pay and know more about family planning',['education makes people unable to have children','schools forbid marriage'],'Educated women often marry later, work for pay and know more about family planning, so on average they have fewer children.'],
  ['How does access to family planning affect birth rates?','it lowers them, because people can choose how many children to have',['it raises them','it has no effect'],'Family planning lets people choose how many children to have and when, so birth rates usually fall when access improves.'],
  ['When more women join the paid workforce, what usually happens to family size?','it gets smaller',['it gets larger','it stays exactly the same'],'Women in paid work often delay or limit childbearing, and children cost more time and money, so families tend to get smaller.'],
  ['Which stage of the demographic transition is linked to rising education and work for women and falling births?','stage 3',['stage 1','stage 2'],'In stage 3, birth rates fall as education and paid work for women rise and children survive more often. Stage 2 still has high births.'],
  ['In places where women marry very young, what is usually true of the fertility rate?','it is higher',['it is lower','it is zero'],'Women who marry very young have more years to bear children and less schooling, so fertility rates tend to be higher.'],
  ['Why might families have fewer children as more of them live in cities?','children cost more to raise and are less needed as farm workers',['cities ban large families everywhere','city water lowers fertility'],'In cities, children cost more to house and school and are not needed as farm workers, so families tend to have fewer children.'],
  ['What is one way changing roles for women can affect the economy?','a larger and more skilled workforce',['fewer people of working age','the end of all farming'],'When more women are educated and join paid work, the workforce gets larger and more skilled, which can help the economy grow.'],
  ['Lower infant mortality often leads families to have fewer children. Why?','parents no longer need many births to be sure some children survive',['healthy babies grow up faster','medicine lowers fertility directly'],'When children are likely to survive, parents no longer need many births to be sure some live to adulthood, so families get smaller.'],
  ['In many countries, what has gone along with women\'s rising education?','a falling birth rate',['a rising death rate','a rising birth rate'],'In many countries, more schooling for women has gone along with falling birth rates.']],tab('Women and demographic change',[['more schooling','fewer children'],['paid work','smaller families'],['family planning','chosen family size']],['Effect']));
 /* aging: old-age dependency and its effects */
 for(const [o,w] of [[15,50],[12,60],[28,56],[9,45]])put('aging',`A fictional country has ${o} million people aged 65 and over and ${w} million aged 15-64. What is its old-age dependency ratio?`,Math.round(o/w*100*1e6)/1e6,tab('In millions',[['ages 65+',`${o}`],['ages 15-64',`${w}`]]),`${o} ÷ ${w} × 100 = ${pct(o/w*100)} older people for every 100 people of working age.`);
 for(const [o,t] of [[20,80],[9,60],[33,120]])put('aging',`Of a fictional country's ${t} million people, ${o} million are aged 65 or over. What percent of the population is that?`,Math.round(o/t*100*1e6)/1e6,tab('In millions',[['population',`${t}`],['ages 65+',`${o}`]]),`${o} ÷ ${t} × 100 = ${pct(o/t*100)}%.`);
 ask('aging',[['What usually causes a population to age?','low birth rates and longer lives',['high birth rates','a rising death rate among the old'],'Low birth rates mean fewer young people, and longer lives mean more older people, so the population\'s average age rises.'],
  ['Why does an aging population strain a government\'s budget?','more people draw pensions and need health care while fewer work and pay taxes',['older people pay more taxes','fewer schools are needed'],'Older people draw pensions and need more health care, while fewer working-age people pay taxes, so budgets are squeezed.'],
  ['Which country has one of the oldest populations in the world?','Japan',['Niger','Afghanistan'],'Japan has one of the world\'s oldest populations, with low births and long lives. Niger and Afghanistan have very young populations.'],
  ['Which is a common response to an aging, shrinking workforce?','raising the retirement age or welcoming immigrants',['banning immigration','lowering the retirement age to 40'],'To keep enough workers, aging countries often raise the retirement age or welcome immigrants. Banning immigration would shrink the workforce more.'],
  ['What shape does the population pyramid of an aging country tend to have?','a narrow base with wide upper bars',['a very wide base','a perfect triangle'],'Few births make a narrow base, and many older people make wide upper bars. A wide base shows a young, growing population.'],
  ['As a population ages, which services are likely to be needed more?','health care and care for older people',['primary schools','maternity wards'],'An older population needs more health care and elder care. Fewer births mean less need for primary schools and maternity wards.']],tab('Aging populations',[['cause','few births, longer lives'],['strain','pensions, health care'],['responses','later retirement, immigration']],['']));
 /* migration: Ravenstein's laws and intervening obstacles */
 ask('migration',[['According to Ravenstein, how far do most migrants move?','a short distance',['across an ocean','to the farthest city they can reach'],'Ravenstein observed that most migrants move only a short distance, which fits distance decay.'],
  ['According to Ravenstein, where do long-distance migrants usually go?','to big cities with jobs and trade',['to remote farmland','to the nearest village'],'Ravenstein said long-distance migrants usually head for big cities, which offer jobs and trade.'],
  ['Ravenstein said every flow of migrants produces what?','a smaller counterflow back',['an equal flow of goods','a ban on migration'],'Ravenstein said every migration flow produces a smaller counterflow, as some people return or move the other way.'],
  ['According to Ravenstein, what is the most common reason people migrate?','economic reasons, such as work',['the weather alone','religious festivals'],'Ravenstein found that most people migrate for economic reasons, such as better work.'],
  ['A mountain range or a strict border stops a migrant partway. What is this called?','an intervening obstacle',['a pull factor','a remittance'],'An intervening obstacle is a barrier, like a mountain range or a strict border, that blocks or slows a migrant on the way.'],
  ['A migrant heading for a big city stops in a town along the way that has a good job. What is this called?','an intervening opportunity',['an intervening obstacle','a push factor'],'An intervening opportunity is a chance, like a good job, that a migrant finds along the way, so they stop before the planned destination.']],tab('Ravenstein\'s laws',[['distance','most move short distances'],['long moves','to big cities'],['counterflow','every flow has one'],['reason','mostly economic']],['Law']));
 /* kinds: refugees, internally displaced people and asylum seekers */
 ask('kinds',[['A family flees a war and crosses into a neighboring country for safety. What are they?','refugees',['internally displaced people','guest workers'],'Refugees flee war or persecution and cross an international border. Those who stay inside their country are internally displaced.'],
  ['A family is forced from home by fighting but stays inside its own country. What are they?','internally displaced people',['refugees','asylum seekers'],'Internally displaced people are forced from home but stay within their own country. Refugees cross an international border.'],
  ['A person has asked another country for protection and is waiting for a decision. What is this person called?','an asylum seeker',['a guest worker','an internal migrant'],'An asylum seeker has asked another country for protection and awaits a decision on refugee status.'],
  ['What makes someone a refugee rather than an internally displaced person?','they have crossed an international border',['they moved by choice','they moved for a better job'],'Crossing an international border is what makes someone a refugee. Internally displaced people flee but stay in their own country.'],
  ['Which is an example of voluntary migration?','a nurse moving abroad for a better-paid job',['a family fleeing a flood','people forced out by a war'],'Voluntary migration is a choice, such as moving for a better-paid job. Fleeing floods or war is forced migration.'],
  ['Why is it hard to draw a sharp line between forced and voluntary migration?','push factors like poverty can leave people little real choice',['all migration is voluntary','all migration is forced'],'Push factors like poverty, drought or insecurity can leave people little real choice, so forced and voluntary migration blur.']],tab('Forced migrants',[['refugee','fled across a border'],['internally displaced person','fled, but still in the home country'],['asylum seeker','asked for protection, waiting']],['Means']));
 /* effects: remittances, brain drain, chain and step migration, guest workers, transhumance */
 for(const [r,g] of [[6,40],[3,25],[9,36]])put('effects',`Migrants from a fictional country send home $${r} billion a year, and the country's GDP is $${g} billion. Remittances equal what percent of GDP?`,Math.round(r/g*100*1e6)/1e6,tab('A fictional country',[['remittances',`$${r} billion`],['GDP',`$${g} billion`]]),`${r} ÷ ${g} × 100 = ${pct(r/g*100)}% of GDP.`);
 ask('effects',[['What are remittances?','money migrants send back to their home country',['taxes migrants pay to their new country','loans from the World Bank'],'Remittances are money migrants send home to family. For some countries, they are a large share of national income.'],
  ['Many doctors and engineers leave a country for jobs abroad. What is this called?','brain drain',['chain migration','transhumance'],'Brain drain is the loss of educated, skilled workers, like doctors and engineers, who leave for jobs abroad.'],
  ['A woman moves abroad, and later her brother and cousins follow her to the same city. What is this called?','chain migration',['step migration','brain drain'],'Chain migration is when migrants follow family or friends who moved before them, often to the same place.'],
  ['A family moves from a village to a town, then to a regional city, then to the capital. What is this called?','step migration',['chain migration','counterurbanization'],'Step migration is moving in stages, from village to town to city, rather than in one move.'],
  ['Workers are invited into a country for a set time to fill jobs. What are they called?','guest workers',['refugees','internally displaced people'],'Guest workers are invited into a country for a set time to fill jobs, often in farming, building or factories.'],
  ['Herders move their animals between mountain pastures in summer and valley pastures in winter. What is this called?','transhumance',['brain drain','chain migration'],'Transhumance is the seasonal movement of herders and animals between summer mountain pastures and winter valley pastures.'],
  ['Which is a common effect of emigration on the home country?','remittances flow in, but skilled workers may be lost',['its population always grows faster','it gains many new skilled workers'],'Emigrants often send remittances home, but the home country can lose skilled workers, a brain drain.'],
  ['Which is a common effect of immigration on the receiving country?','more workers and greater cultural diversity',['a smaller workforce','fewer languages spoken'],'Immigrants add workers and bring their languages, foods and customs, so the receiving country gains workers and diversity.'],
  ['People leave cities to live in small towns and the countryside. What is this called?','counterurbanization',['chain migration','transhumance'],'Counterurbanization is people moving from cities to small towns and the countryside, the reverse of urbanization.']],tab('Effects of migration',[['remittances','money sent home'],['brain drain','skilled people leave'],['chain migration','following family'],['step migration','moving in stages']],['Means']),1);
}};
